34	 * V-transport scratch page, or the HTIF MMIO window -- ROADMAP_LINUX_RUNTIME.md
35	 * U9: the V-scratch/window checks were deferred from U3 until a mode that
36	 * actually reserves them (hybrid) existed to test against, but run
37	 * unconditionally here since they are harmless (nothing is ever there
38	 * under fast/cycle) and correctness should not depend on which mode
39	 * booted this image. */
40	static int overlaps_reserved(uint64_t vaddr, uint64_t memsz, uint64_t mem_size)
41	{
42	  const uint64_t vlinux_base = (uint64_t) (uintptr_t) _vlinux_base;
43	  const uint64_t vlinux_end = (uint64_t) (uintptr_t) _stack;
44	  if (range_overlaps(vaddr, memsz, vlinux_base, vlinux_end)) return 1;
45	
46	  const uint64_t scratch_base = mem_size - HYBRID_V_SCRATCH_BYTES;
47	  if (range_overlaps(vaddr, memsz, scratch_base, mem_size)) return 1;
48	
49	  if (range_overlaps(vaddr, memsz, HTIF_MMIO_BASE,
50	                     HTIF_MMIO_BASE + HTIF_MMIO_SIZE))
51	    return 1;
52	
53	  return 0;
54	}
